#include <stdio.h>
#include <unistd.h>
#include <limits.h>

#define BUF_SZ (1 << 12)

static inline int is_ws(unsigned char b)
{
    return b == ' ' || b == '\t' || b == '\n' || b == '\v' || b == '\f' || b == '\r';
}

int main(void)
{
    char buf[BUF_SZ];
    size_t n;

    int lines = 0, words = 0, bytes = 0, maxlen = 0;
    int cur_line_len = 0;       /* chars in current line so far (no \n count) */
    int in_word = 0;            /* inside a word in current buffer segment */

    /* If we ended the previous read at the start of a word */
    int prev_buffer_started_word = 0;

    while ((size_t)(n = read(STDIN_FILENO, buf, BUF_SZ)) > 0) {
        for (size_t i = 0; i < n; ++i) {
            unsigned char b = (unsigned char)buf[i];

            bytes++;

            if (b == '\n') {
                /* The current line (before \n) is finished */
                if (cur_line_len > maxlen)
                    maxlen = cur_line_len;
                cur_line_len = 0;
                lines++;
                in_word = 0;
                prev_buffer_started_word = 0;
            } else {
                cur_line_len++;
                if (!is_ws(b)) {
                    /* byte belongs to a word */
                    if (!in_word) {
                        in_word = 1;
                        words++;
                    }
                } else {
                    in_word = 0;
                }
            }
        }

        prev_buffer_started_word = in_word;
    }

    /* Remaining bytes without trailing \n: still a line */
    if (cur_line_len > maxlen)
        maxlen = cur_line_len;

    printf("%d %d %d %d\n", lines, words, bytes, maxlen);
    return 0;
}

